-- The public menu address is a readable slug plus a permanent random code (brief CF-14, D68):
-- `/m/<slug>-<public_id>`. The code alone finds the venue, so slugs stop being unique (this
-- replaces 0013 and T61) and a venue can be renamed without breaking a link.
--
-- The column, the index and the checks are generated by drizzle-kit from src/schema.ts; the
-- backfill and the checks around it are written by hand. One transaction (the migrator runs
-- pending migrations in one), in this order:
--   0. `venues` stops forcing row-level security on its owner for the length of this
--      transaction and stops touching `updated_at`: on a database whose owner does not bypass RLS
--      (Supabase's `postgres`) the owner would otherwise see no row at all, and giving a venue a
--      code should leave every other column as it was. Both come back at the end; ALTER TABLE
--      holds an ACCESS EXCLUSIVE lock until commit, so nobody else sees the table meanwhile;
--   1. the column, nullable, and its unique index (several NULLs are allowed, so it can exist
--      before the backfill and decide collisions during it);
--   2. backfill: every venue gets 12 characters of a-z0-9. They come from `gen_random_uuid()`
--      bytes by rejection sampling, exactly like core's `newPublicId` (a byte of 252 or more is
--      dropped, so the 36 characters are equally likely; bytes 6 and 8 of a UUID hold its fixed
--      version and variant bits and are skipped). A clash with a code already given is drawn
--      again;
--   3. post-check: refuse if a venue is left without a code (it would mean the owner cannot see the
--      rows), then NOT NULL and the format check;
--   4. drop the two unique rules on the slug: the per-tenant constraint of 0000 and the global
--      index of 0013 (generated);
--   5. back to normal: updated_at touched again, RLS forced on the owner again.
-- Old published files `v/<slug>.json` are not migrated: only test data exists. They stay in the
-- store and nothing reads them again.

-- 0. Owner access for the backfill; undone at step 5.
ALTER TABLE "restro"."venues" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."venues" DISABLE TRIGGER "venues_touch_updated_at";--> statement-breakpoint

-- 1. The column and its unique index.
ALTER TABLE "restro"."venues" ADD COLUMN "public_id" text;--> statement-breakpoint
CREATE UNIQUE INDEX "venues_public_id_unique" ON "restro"."venues" USING btree ("public_id");--> statement-breakpoint

-- 2. Give every venue a code.
DO $$
DECLARE
  alphabet constant text := '0123456789abcdefghijklmnopqrstuvwxyz';
  venue_row record;
  candidate text;
  random_bytes bytea;
  byte_value int;
  byte_position int;
BEGIN
  FOR venue_row IN SELECT id FROM restro.venues WHERE public_id IS NULL ORDER BY id LOOP
    LOOP
      candidate := '';
      WHILE length(candidate) < 12 LOOP
        random_bytes := uuid_send(gen_random_uuid());
        FOR byte_position IN 0..15 LOOP
          CONTINUE WHEN byte_position IN (6, 8);
          byte_value := get_byte(random_bytes, byte_position);
          IF byte_value < 252 AND length(candidate) < 12 THEN
            candidate := candidate || substr(alphabet, (byte_value % 36) + 1, 1);
          END IF;
        END LOOP;
      END LOOP;
      BEGIN
        UPDATE restro.venues SET public_id = candidate WHERE id = venue_row.id;
        EXIT;
      EXCEPTION WHEN unique_violation THEN
        -- Taken by another venue: draw again.
        NULL;
      END;
    END LOOP;
  END LOOP;
END
$$;--> statement-breakpoint

-- 3. Post-check, then the rules the column ends up with.
DO $$
DECLARE
  without_code bigint;
BEGIN
  SELECT count(*) INTO without_code FROM restro.venues WHERE public_id IS NULL;
  IF without_code > 0 THEN
    RAISE EXCEPTION '0015_venues_public_id: % venues are still without a public code; the migration owner must be able to update restro.venues (superuser, BYPASSRLS, or the table owner)', without_code;
  END IF;
END
$$;--> statement-breakpoint
ALTER TABLE "restro"."venues" ALTER COLUMN "public_id" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "restro"."venues" ADD CONSTRAINT "venues_public_id_format" CHECK ("restro"."venues"."public_id" ~ '^[a-z0-9]{12}$');--> statement-breakpoint

-- 4. Slugs are free (generated by drizzle-kit).
ALTER TABLE "restro"."venues" DROP CONSTRAINT "venues_tenant_id_slug_unique";--> statement-breakpoint
DROP INDEX "restro"."venues_slug_unique";--> statement-breakpoint

-- 5. Back to normal.
ALTER TABLE "restro"."venues" ENABLE TRIGGER "venues_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."venues" FORCE ROW LEVEL SECURITY;
